import gi
gi.require_version('Gtk', '4.0')
from gi.repository import Gtk

def create_window(builder):
    tasks = builder.get_object('tasks')
    entry = builder.get_object('entry')
    def add(text):
        tasks.append(Gtk.CheckButton(label=text))
    for text in ('Plan something for the weekend', 'Pick a recipe to cook together', 'Get outside for a little while'):
        add(text)
    def submit(*args):
        text = entry.get_text().strip()
        if text:
            add(text)
            entry.set_text('')
    builder.get_object('add').connect('clicked', submit)
    entry.connect('activate', submit)
    return builder.get_object('window')

